/* ---------------- Spells: Player's Handbook (2024) ----------------
   GENERATED: the 2024 Player's Handbook's spells (chapter 7, pp. 238-343)
   as the app shows them to a character on the 2024 rules or with a 2024
   class (see js/core/spell-edition.js): the book's level, school, casting
   time, range, components, duration, ritual tag and class lists (the
   artificer's, which the book has no list for, kept from the 2014 entry),
   with a summary checked against the book's text, spell by spell. The
   headers come from 5etools' XPHB data and were compared with every header
   printed in the book (the one difference, Flaming Sphere's school, follows
   the book). "Melf's Acid Arrow" is the app's Acid Arrow (SPELL_ALIASES).
   A spell not in the 2024 book keeps its 2014 entry for everyone.
   Same fields as SPELL_DATA (js/data/spells.js), source "XPHB". */
var SCHOOLS = {Abj:"Abjuration", Con:"Conjuration", Div:"Divination", Enc:"Enchantment", Evo:"Evocation", Ill:"Illusion", Nec:"Necromancy", Tra:"Transmutation"};
function s(level, school, castingTime, range, components, duration, classes, summary, opts){
  opts = opts || {};
  return {level: level, school: SCHOOLS[school], castingTime: castingTime, range: range, components: components,
    material: opts.material || "", duration: duration, concentration: /^Concentration/.test(duration), ritual: !!opts.ritual,
    classes: classes ? classes.split(",") : [], tashaClasses: [], source: "XPHB", summary: summary};
}

